// The System layer (src/system) against .NET: every case of test/system/cases.json (generated by
// scripts/gen-sys-cases.mjs) is evaluated by the TS port and compared with the result of
// oracle/SysOracle.cs (test/oracle-out/sys.json, regenerated by scripts/oracle.sh).
// SYS_CASES / SYS_ORACLE override both paths (for working on a subset); SYS_ALL=1 lists every
// mismatch, SYS_VERBOSE=1 prints the case and known-deviation counts per area, SYS_NORULES=1
// disables the rule-based known deviations (to see which cases they excuse).
// Known deviations live in test/system/eval/<area>.ts (`deviations`, `deviationRules`) and in
// docs/deviations.md.
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { deviationRules, deviations, run, type Case, type Result } from './sys-eval.js';
import { oracleOut } from '../setup/oracle-out.js';

const casesFile = process.env.SYS_CASES ?? join(__dirname, 'cases.json');
const oracleFile = process.env.SYS_ORACLE ?? join(oracleOut, 'sys.json');

describe.skipIf(!existsSync(casesFile) || !existsSync(oracleFile))('System layer parity with .NET', () => {
  const cases: Case[] = JSON.parse(readFileSync(casesFile, 'utf8'));
  // The suite body runs even when skipped (vitest collects the tests): read only what exists.
  const expected: Result[] = existsSync(oracleFile) ? JSON.parse(readFileSync(oracleFile, 'utf8')) : [];

  it('oracle output belongs to the cases', () => {
    expect(expected.length).toBe(cases.length);
  });

  const areas = [...new Set(cases.map((c) => c.area))];
  for (const area of areas) {
    it(area, () => {
      const mismatches: string[] = [];
      const staleDeviations: string[] = [];
      let n = 0;
      let known = 0;
      cases.forEach((c, i) => {
        if (c.area !== area) return;
        n++;
        const key = `${c.fn} ${JSON.stringify(c.args)}`;
        const got = run(c);
        const same = JSON.stringify(got) === JSON.stringify(expected[i]);
        if (key in deviations) {
          if (same) staleDeviations.push(key);
          else known++;
        } else if (!same && !process.env.SYS_NORULES && deviationRules.some((r) => r.test(c.fn, c.args))) {
          known++;
        } else if (!same) {
          mismatches.push(`${key}\n    .NET: ${JSON.stringify(expected[i])}\n    TS:   ${JSON.stringify(got)}`);
        }
      });
      if (process.env.SYS_VERBOSE) process.stderr.write(`${area}: ${n} cases, ${known} known deviations\n`);
      expect(n).toBeGreaterThan(0);
      expect(staleDeviations, 'deviations that now match .NET (remove them from the list)').toEqual([]);
      expect(mismatches.slice(0, process.env.SYS_ALL ? undefined : 40).join('\n'), `${mismatches.length} of ${n} cases differ`).toBe('');
    });
  }
});
